            // a *different* bearer for the retry — that makes the
            // exactly-2 PUT count meaningful: the second PUT carries
            // Bearer token-B (proving the refresh ran), and the absence
            // of a third PUT proves no second refresh was attempted.
            // The 7200 s lifetime keeps the retry's credential live, which is
            // what puts the b.e49 verdict on `Permanent` — see the doc above.
            write_token_file(&token_path, "token-B", 7_200);

            let store = make_test_adapter(&mock_server, provider);
            let err = store
                .put_session_checkpoint(
                    "sess-abc",
                    Bytes::from_static(b"body"),
                    CheckpointMeta::default(),
                )
                .await
                .expect_err("two consecutive 401s must surface as an error");

            assert!(
                err.is_permanent(),
                "an unexpired credential was presented on the retry and rejected — that is the \
                 operator escalation, so the verdict must be Permanent. Got {err:?}"
            );

            let received = mock_server
                .received_requests()
                .await
                .expect("mock server records requests");
            assert_eq!(
                received.len(),
                2,
                "outer auth-attempt loop is bounded at 2 iterations; expected exactly 2 on-wire PUTs, got {}",
                received.len()
            );

